import{_ as s,o as t,c as a,a2 as o}from"./chunks/framework.7R1OEGYz.js";const u=JSON.parse('{"title":"Support","description":"","frontmatter":{},"headers":[],"relativePath":"support.md","filePath":"support.md","lastUpdated":1794096855000}'),i={name:"support.md"};function r(n,e,l,p,h,d){return t(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="support" tabindex="-1">Support <a class="header-anchor" href="#support" aria-label="Permalink to &quot;Support&quot;">​</a></h1><p>What support covers, how to reach it, and how to report a problem without handing over secrets.</p><p><strong>Edition:</strong> Community (public issues) · Enterprise customers (email support and onboarding, per the order form) · <strong>Who:</strong> operators and administrators of an instance</p><h2 id="community-edition" tabindex="-1">Community edition <a class="header-anchor" href="#community-edition" aria-label="Permalink to &quot;Community edition&quot;">​</a></h2><p>Report bugs and ask questions as <a href="https://github.com/open-agenthub/open-agenthub/issues" target="_blank" rel="noreferrer">GitHub issues</a>. Issues are public and answered on a best-effort basis, without a response time. Do not post logs, values files or screenshots that contain credentials, hostnames or user content there; see <a href="#reporting-a-problem">Reporting a problem</a>.</p><p>Report suspected vulnerabilities privately to <code>open-agenthub@mail.on-mb.com</code>, never as a public issue.</p><h2 id="enterprise-customers" tabindex="-1">Enterprise customers <a class="header-anchor" href="#enterprise-customers" aria-label="Permalink to &quot;Enterprise customers&quot;">​</a></h2><p>Support does not access your systems, accounts or data; you run all commands yourself, also during a screen share.</p><div class="warning custom-block"><p class="custom-block-title">DRAFT: support terms</p><p>The terms in this section follow a draft order form that is not yet approved. Your signed order form applies.</p></div><h3 id="how-to-reach-support" tabindex="-1">How to reach support <a class="header-anchor" href="#how-to-reach-support" aria-label="Permalink to &quot;How to reach support&quot;">​</a></h3><ul><li><strong>By email</strong> to <code>SUPPORT_EMAIL</code>, on business days.</li><li><strong>Acknowledgement:</strong> you get a reply confirming receipt within one business day.</li><li><strong>No service level:</strong> there is no guaranteed availability, response time or resolution time, and no 24/7 support.</li></ul><p>Support works from what you send. See <a href="/docs/pilot-setup#who-operates-what">Who operates what</a>.</p><h3 id="onboarding" tabindex="-1">Onboarding <a class="header-anchor" href="#onboarding" aria-label="Permalink to &quot;Onboarding&quot;">​</a></h3><p>Enterprise customers get two remote sessions of 60 minutes each, within 30 days of the start:</p><ol><li><strong>Setup review:</strong> your installation, TLS, OIDC, <code>ee.admins</code> and, if you use one, a private certificate authority (<code>backend.trustedCaConfigMap</code>). Prepare by following <a href="/docs/pilot-setup">Pilot setup</a>.</li><li><strong>First team workflow:</strong> <a href="/docs/sharing">sharing</a>, <a href="/docs/admin#usage-limits">usage limits</a>, the <a href="/docs/admin#allowed-agents">agent allowlist</a> and <a href="/docs/sharing#mcp-restrictions-for-the-whole-session">MCP restrictions for sessions</a>.</li></ol><p>You operate your systems yourself, also while sharing your screen; we explain and watch, but do not take control.</p><h3 id="in-scope" tabindex="-1">In scope <a class="header-anchor" href="#in-scope" aria-label="Permalink to &quot;In scope&quot;">​</a></h3><ul><li><strong>Installation</strong> of a supported release, with the quickstart or the Helm chart, as described on <a href="/docs/getting-started">Install</a> and <a href="/docs/pilot-setup">Pilot setup</a>: chart values, team login with OIDC, object storage, and activating the licence.</li><li><strong>Upgrades</strong> along the documented path on <a href="/docs/upgrading">Upgrading</a>, including the steps the release notes ask for.</li><li><strong>Documented features of your edition</strong>, as described on these pages and marked Community or Enterprise. Features marked experimental, such as the <a href="/docs/provider-switching">provider switch</a>, are covered as documented, including their known limits.</li><li><strong>Licence questions</strong>: activation, renewal health and seat counts under <strong>Settings → License</strong> and <strong>Settings → Users &amp; seats</strong>.</li></ul><h3 id="not-in-scope" tabindex="-1">Not in scope <a class="header-anchor" href="#not-in-scope" aria-label="Permalink to &quot;Not in scope&quot;">​</a></h3><p>Unless your order form says otherwise:</p><ul><li>Your Kubernetes cluster, ingress, DNS, certificates, identity provider, Git host, database or object storage themselves, beyond the settings Open AgentHub needs from them.</li><li>The agent CLIs&#39; own behaviour and your accounts with model providers; Open AgentHub runs the CLI versions its release ships, and the provider&#39;s terms apply to your account.</li><li>Modified source code, custom runtime images, and releases older than the current one, where the problem is already fixed in a newer release.</li><li>The work agents do in your repositories.</li></ul><h2 id="reporting-a-problem" tabindex="-1">Reporting a problem <a class="header-anchor" href="#reporting-a-problem" aria-label="Permalink to &quot;Reporting a problem&quot;">​</a></h2><p>Send what is needed to reproduce the problem, and <strong>nothing that contains secrets or personal data</strong>. Include:</p><ol><li><p><strong>Versions</strong>: the output of</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deployment</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub-backend</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jsonpath=&#39;{.spec.template.spec.containers[0].image}&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span></span></code></pre></div></li><li><p><strong>What happened</strong>: the steps, what you expected, what you saw, and the time (with time zone).</p></li><li><p><strong>Edition and agent</strong>: Community or Enterprise, and which agent the session ran (Claude Code, Codex, Cursor, OpenClaw or OpenCode).</p></li><li><p><strong>Pod status</strong>, as pod names and states only:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pods</span></span></code></pre></div></li></ol><p><strong>By default, send no logs.</strong> Do not send logs or <code>kubectl describe</code> output unless support asks for a specific excerpt and you have agreed to share it with your provider beforehand; this may require a data processing agreement. Logs and <code>describe</code> output can contain environment values, events, user names, hostnames and session titles.</p><p><strong>Never send:</strong></p><ul><li>the API key, personal API tokens, licence tokens, or session access tokens;</li><li>the Secrets <code>agenthub-data-protection</code>, <code>agenthub-api-key</code>, <code>postgres-secret</code> or your Git and model provider credentials;</li><li>your values file as it is. If the configuration matters, remove passwords, keys, tokens and connection strings first, or name only the values you changed;</li><li>logs, <code>kubectl describe</code> output, database dumps, session transcripts or files from a session, unless support asks for a specific item and you have agreed this with your provider beforehand (this may require a data processing agreement).</li></ul><p>If you sent something by mistake, rotate it: a credential that has left your organisation should be treated as exposed.</p><p>A way to collect such a report as one bundle, with secrets removed, will follow. Review that bundle too before you send it.</p><h2 id="before-you-contact-support" tabindex="-1">Before you contact support <a class="header-anchor" href="#before-you-contact-support" aria-label="Permalink to &quot;Before you contact support&quot;">​</a></h2><ul><li><a href="/docs/troubleshooting">Troubleshooting</a> covers known errors, for example Helm <code>nil pointer</code> failures and schema lock waits at startup.</li><li><a href="/docs/upgrading">Upgrading</a> lists what each release asks of you.</li><li>For licence renewal problems, check <a href="/docs/admin#check-renewal-health">renewal health</a> first.</li></ul>`,31)])])}const g=s(i,[["render",r]]);export{u as __pageData,g as default};
